
// ---------- CP-79 (Jenny, Nov 18): Yawn sound as a Developer choice ----------
// "put today, A2, B2 and AB in the next UAT as a Developer choice (today's is the default). I'll pick on my phone."
// Settings -> Developer -> Engineer tools -> "Yawn sound": Today / A2 / B2 / AB, saved on this phone
// (localStorage catpusher.uat.cp79yawn.v1). Every sfx.wild2('yawn') (the wheel's Yawn) plays the chosen sound; Today is the
// code-made one, unchanged. A2/B2/AB: cleaned real recordings (work/cp79-yawn-sound/polish.py; Freesound 841188 by
// designerschoice and 764743 by 242011Vee, CC BY 4.0, credits in tickets/CP-79.md), decoded once and played on the effects
// master at CP79.gain (0.35) x the same volume wild2 uses, which matches today's loudness. Off/background plays nothing.
const CP79=(()=>{const B64={A2:"",B2:"",AB:""};
 const KEY='catpusher.uat.cp79yawn.v1',CHOICES=['today','A2','B2','AB'],NAMES={today:'Today',A2:'A2',B2:'B2',AB:'AB'};
 let pick='today';try{const v=localStorage.getItem(KEY);if(CHOICES.includes(v))pick=v;}catch(e){}
 const bufs={},asked={};const stats={played:{}};
 function load(k){if(asked[k]||!B64[k])return;asked[k]=true;try{const b=atob(B64[k]),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);
  if(!sfx._dec(u.buffer,x=>{bufs[k]=x;}))asked[k]=false;else setTimeout(()=>{if(!bufs[k])asked[k]=false;},2000);}catch(e){asked[k]=false;}}
 function set(k){if(!CHOICES.includes(k))return;pick=k;try{localStorage.setItem(KEY,k);}catch(e){}load(k);}
 function get(){return pick;}
 function warm(){if(pick!=='today'&&!bufs[pick])load(pick);}
 return {B64,KEY,CHOICES,NAMES,gain:.35,bufs,asked,load,set,get,warm,stats};})();
const __cp79Wild2=sfx.wild2;
sfx.wild2=function(kind,vol=1,...a){
 if(kind!=='yawn'||CP79.get()==='today')return __cp79Wild2.call(this,kind,vol,...a);
 const k=CP79.get();CP79.load(k);const v=vol*(typeof pickupFx==='object'?pickupFx.volume:1);
 if(CP79.bufs[k]&&this._playBuf(CP79.bufs[k],v*CP79.gain)){CP79.stats.played[k]=(CP79.stats.played[k]||0)+1;return;}
 return __cp79Wild2.call(this,kind,vol,...a);}; // not decoded yet (first tap only): today's sound, so a Yawn is never silent
// Decode the chosen sound as soon as the audio is ready (before any Yawn): retried each frame until it's in.
const __cp79Update=update;update=function(dt){__cp79Update(dt);try{CP79.warm();}catch(e){}};
// The choice in Engineer tools (built after CP-70 lays out the Developer panel). Tapping a choice also plays it once.
const __cp79Credits=openCredits;
openCredits=function(){const r=__cp79Credits.apply(this,arguments);try{
 const eng=panel.querySelector&&panel.querySelector('#cp70-engineer');if(!S.dev||!eng||eng.querySelector('#cp79-yawn'))return r;
 const box=document.createElement('div');box.id='cp79-yawn';const h=document.createElement('h3');h.textContent='Yawn sound';box.appendChild(h);
 const btns=[];const paint=()=>btns.forEach(b=>{const on=b.dataset.yawn===CP79.get();b.textContent=(on?'✓ ':'')+CP79.NAMES[b.dataset.yawn];b.style.fontWeight=on?'700':'400';});
 for(const k of CP79.CHOICES){const b=document.createElement('button');b.dataset.yawn=k;b.style.marginRight='6px';
  b.onclick=()=>{CP79.set(k);paint();setTimeout(()=>{try{sfx.wild2('yawn',1);}catch(e){}},k==='today'||CP79.bufs[k]?0:250);};btns.push(b);box.appendChild(b);}
 paint();const sum=eng.querySelector('summary');if(sum&&sum.nextSibling)eng.insertBefore(box,sum.nextSibling);else eng.appendChild(box);}catch(e){}return r;};
